cat > solution.wand <<'EOF'
import IO
import List
import String
import Regex
import Map
import Int
import Proc

let dur_re = r/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/

let num s = if s == "" then 0 else Int.of_string! s

-- seconds of a duration text, or None when malformed
let parse_dur d =
  match Regex.capture dur_re d with
  | [_, h, m, s] ->
    if d == "" then None else Some (num h * 3600 + num m * 60 + num s)
  | _ -> None

let fmt t =
  let h = t / 3600;
  let m = (t % 3600) / 60;
  let s = t % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if out == "" then "0s" else out

let fail! n =
  IO.println_err "line %{n}: invalid line"
  Proc.exit 1

let step! acc (n, line) =
  match String.words line with
  | [] -> acc
  | [name, d] ->
    match parse_dur d with
    | Some secs ->
      if name == "total" then fail! n else Map.update name secs (fn x -> x + secs) acc
    | None -> fail! n
  | _ -> fail! n

let main! () =
  let lines = String.lines (IO.read_all! ());
  let numbered = List.zip (List.range 1 (List.length lines + 1)) lines;
  let m = List.fold_left step! Map.empty numbered;
  let names = List.sort (Map.keys m);
  List.each (fn k -> IO.println "%{k} %{fmt (Map.get! k m)}") names
  IO.println "total %{fmt (List.fold_left (fn a v -> a + v) 0 (Map.values m))}"

main! ()
EOF
