-- walk a directory, returning relative paths of regular files
let walk! root rel =
  let dir = if String.empty? rel then Path.of_string root else Path.of_string "%{root}/%{rel}";
  let names = List.sort (List.map (fn p -> Path.to_string (Path.basename p)) (FS.list_dir! dir));
  List.flat_map (fn n ->
    let r = if String.empty? rel then n else "%{rel}/%{n}";
    let full = Path.of_string "%{root}/%{r}";
    if FS.dir? full then walk! root r
    else if FS.file? full && String.ends_with? ".txt" n then [r]
    else []) names

let main! args =
  match args with
  | [dir, old, new] ->
    if String.empty? old then
      (IO.println_err "OLD must not be empty"; Proc.exit 2)
    else if !(FS.dir? (Path.of_string dir)) then
      (IO.println_err "not a directory: %{dir}"; Proc.exit 1)
    else
      let files = List.sort (walk! dir "");
      let results = List.filter_map (fn r ->
        let p = Path.of_string "%{dir}/%{r}";
        let text = FS.read_file! p;
        let parts = String.split old text;
        let n = List.length parts - 1;
