          (FS.write_file! p (String.join new parts);
           IO.println "changed %{r} (%{n})";
           Some n)
        else None) files;
      let total = List.fold_left (fn a b -> a + b) 0 results;
      IO.println "changed %{List.length results} files, %{total} replacements"
  | _ -> (IO.println_err "usage: DIR OLD NEW"; Proc.exit 2)

main! (Proc.args ())
